// GENERATED by medusa-integrations: copied from kit/admin/setup.tsx by scripts/kit-sync.mjs. Do not edit by hand.
import { CheckCircleSolid, CircleDottedLine, InformationCircle } from "@medusajs/icons"
import { Badge, Container, Heading, Skeleton, StatusBadge, Text } from "@medusajs/ui"
import { useQuery } from "@tanstack/react-query"

import { sdk } from "./sdk"
import { useKitText } from "./texts"

/** Same shape as the server's `SetupStep` (kit/server/setup.ts). */
export type SetupStep = {
  id: string
  status: "done" | "todo" | "manual"
  optional?: boolean
  params?: Record<string, string | number>
}

/**
 * The installation steps on the Guide tab, each with the status the
 * plugin detected: done, to do (optional or required), or one to check by
 * hand because nothing in the store shows it. Optional steps turn green
 * like the others once they are done.
 */
export const SetupSteps = ({
  steps,
  loading,
  text,
}: {
  steps: SetupStep[] | undefined
  loading: boolean
  /** The plugin's translation of a step: `t(\`<ns>.setup.${id}.${part}\`, params)`. */
  text: StepText
}) => {
  const k = useKitText()
  const list = steps ?? []
  const required = list.filter((s) => !s.optional && s.status !== "manual")
  const requiredDone = required.filter((s) => s.status === "done").length

  return (
    <Container className="overflow-hidden flex flex-col gap-y-3 p-6">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Heading level="h2">{k("setupTitle")}</Heading>
        {!loading && required.length > 0 && (
          <Badge size="2xsmall" color={requiredDone === required.length ? "green" : "orange"}>
            {k("setupProgress", { done: requiredDone, total: required.length })}
          </Badge>
        )}
      </div>
      {loading ? (
        <Skeleton className="h-40" />
      ) : (
        <ol className="flex flex-col gap-y-3">
          {list.map((step, index) => (
            <li key={step.id} className="flex items-start gap-x-3 rounded-lg border border-ui-border-base px-4 py-3">
              <span className="mt-0.5 shrink-0">
                {step.status === "done" ? (
                  <CheckCircleSolid className="text-ui-tag-green-icon" />
                ) : step.status === "manual" ? (
                  <InformationCircle className="text-ui-tag-blue-icon" />
                ) : (
                  <CircleDottedLine className={step.optional ? "text-ui-fg-muted" : "text-ui-tag-orange-icon"} />
                )}
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2">
                  <Text size="small" weight="plus">
                    {index + 1}. {text(step.id, "title", step.params ?? {})}
                  </Text>
                  <StatusBadge color={statusColor(step)}>{k(statusKey(step))}</StatusBadge>
                  {step.optional && step.status === "done" && (
                    <Text size="xsmall" className="text-ui-fg-muted">
                      {k("setupOptionalTag")}
                    </Text>
                  )}
                </div>
                <Text size="small" className="whitespace-pre-line text-ui-fg-subtle">
                  {text(step.id, "body", step.params ?? {})}
                </Text>
              </div>
            </li>
          ))}
        </ol>
      )}
    </Container>
  )
}

type StepText = (id: string, part: "title" | "body", params: Record<string, string | number>) => string

/**
 * `SetupSteps` fed by the plugin's setup endpoint (`GET /admin/<ns>/setup`,
 * answering `{ steps }`). Fetched again each time the Guide tab opens, so a
 * step done a moment ago shows as done.
 */
export const SetupStepsFrom = ({ path, text }: { path: string; text: StepText }) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: ["kit-setup", path],
    queryFn: () => sdk.client.fetch<{ steps: SetupStep[] }>(path),
    refetchOnMount: "always",
  })
  if (isError) return null
  return <SetupSteps steps={data?.steps} loading={isLoading} text={text} />
}

const statusKey = (step: SetupStep) =>
  step.status === "done"
    ? "setupDone"
    : step.status === "manual"
      ? "setupManual"
      : step.optional
        ? "setupOptional"
        : "setupTodo"

const statusColor = (step: SetupStep) =>
  step.status === "done" ? "green" : step.status === "manual" ? "blue" : step.optional ? "grey" : "orange"
